def merge_intervals(intervals: list[tuple[int, int]]) -> list[tuple[int, int]]:
    if not intervals:
        return []

    intervals.sort(key=lambda x: x[0])
    merged = [intervals[0]]

    for current in intervals[1:]:
        last_merged = merged[-1]
        if current[0] <= last_merged[1]:
            merged[-1] = (last_merged[0], max(last_merged[1], current[1]))
        else:
            merged.append(current)

    return merged

def parse_query_string(query: str) -> dict[str, list[str]]:
    if query.startswith('?'):
        query = query[1:]

    pairs = query.split('&')
    result = {}

    for pair in pairs:
        if '=' not in pair:
            key = pair
            value = ""
        else:
            key, value = pair.split('=', 1)

        key = key.replace('+', ' ')
        value = value.replace('+', ' ')
        value = bytes(value, 'utf-8').decode('unicode_escape')

        if key in result:
            result[key].append(value)
        else:
            result[key] = [value]

    return result

def flatten_nested_dict(d: dict, sep: str = ".") -> dict:
    def _flatten(sub_dict, parent_key, sep):
        items = []
        for k, v in sub_dict.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(_flatten(v, new_key, sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    return _flatten(d, "", sep)

def tokenize_arithmetic(expr: str) -> list[str]:
    expr = expr.strip()
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(expr[i:j])
            i = j
        elif expr[i] in "+-*/%()":
            tokens.append(expr[i])
            i += 1
        elif expr[i] == '-':
            if i == 0 or expr[i-1] in "+-*/%(":
                j = i + 1
                while j < len(expr) and expr[j].isdigit():
                    j += 1
                tokens.append(expr[i:j])
                i = j
            else:
                tokens.append(expr[i])
                i += 1
        else:
            i += 1
    return tokens

def validate_credit_card(number: str) -> dict:
    number = number.replace(" ", "").replace("-", "")
    if len(number) < 13 or len(number) > 19 or not number.isdigit():
        return {"valid": False, "brand": "Unknown"}

    def luhn_checksum(card_number):
        digits = [int(d) for d in card_number]
        odd_digits = digits[-1::-2]
        even_digits = digits[-2::-2]
        checksum = sum(odd_digits)
        for d in even_digits:
            checksum += sum(divmod(d * 2, 10))
        return checksum % 10

    if luhn_checksum(number) != 0:
        return {"valid": False, "brand": "Unknown"}

    if number.startswith("4"):
        brand = "Visa"
    elif number.startswith(("51", "52", "53", "54", "55")):
        brand = "Mastercard"
    elif number.startswith(("34", "37")):
        brand = "Amex"
    else:
        brand = "Unknown"

    return {"valid": True, "brand": brand}

def word_wrap_text(text: str, width: int) -> str:
    words = text.split()
    lines = []
    current_line = []

    for word in words:
        if len(' '.join(current_line + [word])) <= width:
            current_line.append(word)
        else:
            lines.append(' '.join(current_line).strip())
            current_line = [word]

    if current_line:
        lines.append(' '.join(current_line).strip())

    return '\n'.join(lines)

def levenshtein_distance(s1: str, s2: str) -> int:
    if len(s1) < len(s2):
        return levenshtein_distance(s2, s1)

    if len(s2) == 0:
        return len(s1)

    previous_row = range(len(s2) + 1)
    for i, c1 in enumerate(s1):
        current_row = [i + 1]
        for j, c2 in enumerate(s2):
            insertions = previous_row[j + 1] + 1
            deletions = current_row[j] + 1
            substitutions = previous_row[j] + (c1 != c2)
            current_row.append(min(insertions, deletions, substitutions))
        previous_row = current_row

    return previous_row[-1]

def longest_common_prefix(strs: list[str]) -> str:
    if not strs:
        return ""

    prefix = strs[0]
    for i in range(1, len(strs)):
        while strs[i].find(prefix) != 0:
            prefix = prefix[:-1]
            if not prefix:
                return ""
    return prefix

def compress_string_rle(s: str) -> str:
    if not s:
        return ""

    compressed = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            compressed.append(s[i - 1] + (str(count) if count > 1 else ''))
            count = 1

    compressed.append(s[-1] + (str(count) if count > 1 else ''))

    return ''.join(compressed)
